{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2158-06-24 05:29:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I’ll be taking care of you today. Can you tell me what brought you to the hospital?"
    },
    {
      "turn_number": 2,
      "time": "2158-06-24 05:30:00",
      "speaker": "Patient",
      "text": "I’ve been really nauseous, throwing up, and my stomach hurts. It’s been going on for a few days."
    },
    {
      "turn_number": 3,
      "time": "2158-06-24 05:31:00",
      "speaker": "Doctor",
      "text": "I see. You have type 1 diabetes, gastroparesis, and chronic pancreatitis. Did you take your insulin recently?"
    },
    {
      "turn_number": 4,
      "time": "2158-06-24 05:32:00",
      "speaker": "Patient",
      "text": "No… I ran out four days ago and couldn’t get more. I know I should’ve, but I just didn’t."
    },
    {
      "turn_number": 5,
      "time": "2158-06-24 05:33:00",
      "speaker": "Doctor",
      "text": "That’s okay. Your blood sugar was very high when you came in—744. That can definitely cause nausea and pain."
    },
    {
      "turn_number": 6,
      "time": "2158-06-24 05:34:00",
      "speaker": "Patient",
      "text": "Oh wow… that’s really high. Is that why I feel so bad?"
    },
    {
      "turn_number": 7,
      "time": "2158-06-24 05:35:00",
      "speaker": "Doctor",
      "text": "Yes. We gave you some insulin through an IV to bring it down. Your glucose dropped to 296, which is better."
    },
    {
      "turn_number": 8,
      "time": "2158-06-24 05:36:00",
      "speaker": "Patient",
      "text": "I also have this cough. I went to urgent care a few days ago. They gave me steroids and antibiotics."
    },
    {
      "turn_number": 9,
      "time": "2158-06-24 05:37:00",
      "speaker": "Doctor",
      "text": "I see. You mentioned prednisone and an antibiotic, but you don’t know which one?"
    },
    {
      "turn_number": 10,
      "time": "2158-06-24 05:38:00",
      "speaker": "Patient",
      "text": "Right. I was supposed to take two steroid pills a day. I don’t remember the other one."
    },
    {
      "turn_number": 11,
      "time": "2158-06-24 05:39:00",
      "speaker": "Doctor",
      "text": "We did a chest X-ray, and your lungs look clear. No pneumonia. Your symptoms sound more like an asthma flare."
    },
    {
      "turn_number": 12,
      "time": "2158-06-24 05:40:00",
      "speaker": "Patient",
      "text": "Oh, okay. Should I keep taking the meds?"
    },
    {
      "turn_number": 13,
      "time": "2158-06-24 05:41:00",
      "speaker": "Doctor",
      "text": "We recommend stopping the steroids and antibiotics. You’re on your regular inhalers, which should help."
    },
    {
      "turn_number": 14,
      "time": "2158-06-24 05:42:00",
      "speaker": "Patient",
      "text": "Alright, I’ll stop them. Thanks."
    },
    {
      "turn_number": 15,
      "time": "2158-06-24 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs show your sodium was low—126—but that’s partly because your blood sugar was so high."
    },
    {
      "turn_number": 16,
      "time": "2158-06-24 08:01:00",
      "speaker": "Patient",
      "text": "Is that dangerous?"
    },
    {
      "turn_number": 17,
      "time": "2158-06-24 08:02:00",
      "speaker": "Doctor",
      "text": "It can be, but now that your sugar is coming down, your sodium is correcting on its own. It’s already up to 135."
    },
    {
      "turn_number": 18,
      "time": "2158-06-24 08:03:00",
      "speaker": "Patient",
      "text": "That’s good to hear."
    },
    {
      "turn_number": 19,
      "time": "2158-06-24 10:30:00",
      "speaker": "Doctor",
      "text": "We’re going to start your tube feeds again. You’ve been on them before, right?"
    },
    {
      "turn_number": 20,
      "time": "2158-06-24 10:31:00",
      "speaker": "Patient",
      "text": "Yes, I have a GJ tube. But sometimes they make me feel bloated."
    },
    {
      "turn_number": 21,
      "time": "2158-06-24 10:32:00",
      "speaker": "Doctor",
      "text": "We’ll monitor that. If you feel bloated, we can try Maalox. It might help with indigestion."
    },
    {
      "turn_number": 22,
      "time": "2158-06-24 12:00:00",
      "speaker": "Doctor",
      "text": "The tube feeding has started. We’ll go slow and check how you tolerate it."
    },
    {
      "turn_number": 23,
      "time": "2158-06-24 12:01:00",
      "speaker": "Patient",
      "text": "Okay, I’ll let you know if I feel sick."
    },
    {
      "turn_number": 24,
      "time": "2158-06-25 07:00:00",
      "speaker": "Doctor",
      "text": "Good news—your nausea and pain have improved. You haven’t vomited since yesterday."
    },
    {
      "turn_number": 25,
      "time": "2158-06-25 07:01:00",
      "speaker": "Patient",
      "text": "Yeah, I feel a lot better. My stomach’s not as upset."
    },
    {
      "turn_number": 26,
      "time": "2158-06-25 07:02:00",
      "speaker": "Doctor",
      "text": "We’re keeping an eye on your blood sugar. You had a low this morning—around 60—so we adjusted your insulin."
    },
    {
      "turn_number": 27,
      "time": "2158-06-25 07:03:00",
      "speaker": "Patient",
      "text": "I felt shaky. Is that from the low sugar?"
    },
    {
      "turn_number": 28,
      "time": "2158-06-25 07:04:00",
      "speaker": "Doctor",
      "text": "Yes, shakiness, sweating, and dizziness are common with hypoglycemia. We lowered your insulin dose to prevent that."
    },
    {
      "turn_number": 29,
      "time": "2158-06-25 07:05:00",
      "speaker": "Patient",
      "text": "Makes sense. I don’t want to feel like that again."
    },
    {
      "turn_number": 30,
      "time": "2158-06-25 14:00:00",
      "speaker": "Doctor",
      "text": "You’ve been doing well on the tube feeds, but your blood sugar spiked over 500 after the last one."
    },
    {
      "turn_number": 31,
      "time": "2158-06-25 14:01:00",
      "speaker": "Patient",
      "text": "Oh no. Should I stop the feeds?"
    },
    {
      "turn_number": 32,
      "time": "2158-06-25 14:02:00",
      "speaker": "Doctor",
      "text": "Not yet. But we’re discussing whether to stop them long-term. You’ve been eating well by mouth, which is great."
    },
    {
      "turn_number": 33,
      "time": "2158-06-25 14:03:00",
      "speaker": "Patient",
      "text": "I have been eating. Maybe I don’t need the tube anymore?"
    },
    {
      "turn_number": 34,
      "time": "2158-06-25 14:04:00",
      "speaker": "Doctor",
      "text": "That’s a possibility. We’ll talk more with your primary doctor. If we stop the feeds, your insulin will need adjusting."
    },
    {
      "turn_number": 35,
      "time": "2158-06-26 08:00:00",
      "speaker": "Doctor",
      "text": "You’ve been on a regular diabetic diet for two days and doing well. No vomiting or severe pain."
    },
    {
      "turn_number": 36,
      "time": "2158-06-26 08:01:00",
      "speaker": "Patient",
      "text": "I feel pretty good. Just a little bloating after the tube feeds."
    },
    {
      "turn_number": 37,
      "time": "2158-06-26 08:02:00",
      "speaker": "Doctor",
      "text": "We gave you Maalox for that, and it helped. We also gave IV Zofran and acetaminophen when you felt worse yesterday."
    },
    {
      "turn_number": 38,
      "time": "2158-06-26 08:03:00",
      "speaker": "Patient",
      "text": "Yeah, that made me feel better fast."
    },
    {
      "turn_number": 39,
      "time": "2158-06-26 08:04:00",
      "speaker": "Doctor",
      "text": "Your HbA1c came back at 11.8%, which shows your sugars have been high over the past few months."
    },
    {
      "turn_number": 40,
      "time": "2158-06-26 08:05:00",
      "speaker": "Patient",
      "text": "I know… I’ve been struggling to keep up with my insulin."
    },
    {
      "turn_number": 41,
      "time": "2158-06-26 08:06:00",
      "speaker": "Doctor",
      "text": "We’re adjusting your insulin regimen. You’ll go home with less insulin on the sliding scale."
    },
    {
      "turn_number": 42,
      "time": "2158-06-26 08:07:00",
      "speaker": "Patient",
      "text": "Will I still take Humalog or Regular insulin?"
    },
    {
      "turn_number": 43,
      "time": "2158-06-26 08:08:00",
      "speaker": "Doctor",
      "text": "You’ll continue insulin lispro—Humalog. It works faster and is better for mealtime control."
    },
    {
      "turn_number": 44,
      "time": "2158-06-26 08:09:00",
      "speaker": "Patient",
      "text": "Okay, I can do that."
    },
    {
      "turn_number": 45,
      "time": "2158-06-27 09:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. We’re planning to discharge you today."
    },
    {
      "turn_number": 46,
      "time": "2158-06-27 09:01:00",
      "speaker": "Patient",
      "text": "That’s great. What do I need to do when I get home?"
    },
    {
      "turn_number": 47,
      "time": "2158-06-27 09:02:00",
      "speaker": "Doctor",
      "text": "Keep taking your insulin as prescribed. Use Maalox if you feel bloated. Stop the steroids and antibiotics."
    },
    {
      "turn_number": 48,
      "time": "2158-06-27 09:03:00",
      "speaker": "Patient",
      "text": "And the tube feeds?"
    },
    {
      "turn_number": 49,
      "time": "2158-06-27 09:04:00",
      "speaker": "Doctor",
      "text": "We’re not stopping them today, but discuss it with your doctor tomorrow. Your insulin may need lowering if you do."
    },
    {
      "turn_number": 50,
      "time": "2158-06-27 09:05:00",
      "speaker": "Patient",
      "text": "Got it. I’ll follow up tomorrow."
    },
    {
      "turn_number": 51,
      "time": "2158-06-27 09:06:00",
      "speaker": "Doctor",
      "text": "You’ll get a printed list of your meds. Review it with your doctor. Call if your sugars are too high or low."
    },
    {
      "turn_number": 52,
      "time": "2158-06-27 09:07:00",
      "speaker": "Patient",
      "text": "I will. Thank you for helping me feel better."
    },
    {
      "turn_number": 53,
      "time": "2158-06-27 09:08:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and we’ll see you in follow-up if needed."
    },
    {
      "turn_number": 54,
      "time": "2158-06-27 10:00:00",
      "speaker": "Doctor",
      "text": "Just a quick check before discharge. How are you feeling?"
    },
    {
      "turn_number": 55,
      "time": "2158-06-27 10:01:00",
      "speaker": "Patient",
      "text": "Good. I walked to the bathroom and back without any issues."
    },
    {
      "turn_number": 56,
      "time": "2158-06-27 10:02:00",
      "speaker": "Doctor",
      "text": "Great. Your blood sugar is 117, and you’re not in pain. You’re cleared to go home."
    },
    {
      "turn_number": 57,
      "time": "2158-06-27 10:03:00",
      "speaker": "Patient",
      "text": "Thank you, Dr. Lee."
    },
    {
      "turn_number": 58,
      "time": "2158-06-27 10:04:00",
      "speaker": "Doctor",
      "text": "Take it easy, and keep up with your care. We’re here if you need us."
    },
    {
      "turn_number": 59,
      "time": "2158-06-27 10:05:00",
      "speaker": "Patient",
      "text": "I will. I’ve learned my lesson about running out of insulin."
    },
    {
      "turn_number": 60,
      "time": "2158-06-27 10:06:00",
      "speaker": "Doctor",
      "text": "That’s good to hear. Staying on track will help prevent this from happening again."
    },
    {
      "turn_number": 61,
      "time": "2158-06-27 10:07:00",
      "speaker": "Patient",
      "text": "I’ll make sure to refill it on time."
    },
    {
      "turn_number": 62,
      "time": "2158-06-27 10:08:00",
      "speaker": "Doctor",
      "text": "Excellent. Someone will bring your discharge papers shortly."
    },
    {
      "turn_number": 63,
      "time": "2158-06-27 10:09:00",
      "speaker": "Patient",
      "text": "Okay, I’ll wait for them."
    },
    {
      "turn_number": 64,
      "time": "2158-06-27 10:10:00",
      "speaker": "Doctor",
      "text": "We also checked your iron levels. They’re low, so keep taking your supplements as prescribed."
    },
    {
      "turn_number": 65,
      "time": "2158-06-27 10:11:00",
      "speaker": "Patient",
      "text": "I’ve been forgetting sometimes, but I’ll try to be more consistent."
    },
    {
      "turn_number": 66,
      "time": "2158-06-27 10:12:00",
      "speaker": "Doctor",
      "text": "Every bit helps. Small changes can make a big difference over time."
    },
    {
      "turn_number": 67,
      "time": "2158-06-27 10:13:00",
      "speaker": "Patient",
      "text": "I’ll do my best."
    }
  ],
  "summary": {
    "admission_start": "2158-06-24 05:29:00",
    "admission_end": "2158-06-27 18:45:00",
    "summary_paragraph": "The patient was admitted for nausea, vomiting, and abdominal pain due to uncontrolled type 1 diabetes from insulin noncompliance. Her blood glucose was 744 on admission, with hyponatremia that corrected as her sugars normalized. Symptoms improved with IV insulin, fluids, and symptom management. She had a history of recent steroid and antibiotic use for a presumed respiratory flare, but imaging showed no pneumonia, and she was advised to discontinue those medications. Tube feeds were resumed, causing mild recurrent bloating, managed with Maalox and anti-nausea medication. Blood sugar control was challenging, with episodes of hypoglycemia and hyperglycemia, leading to insulin regimen adjustments. She tolerated a regular diabetic diet and was discharged home in stable condition with plans to discuss discontinuing tube feeds and optimizing insulin therapy in follow-up.",
    "problems": [
      "Diabetes with neurological manifestations, type I [juvenile type], not stated as uncontrolled",
      "Hyposmolality and/or hyponatremia",
      "Chronic pancreatitis",
      "Gastroparesis",
      "Long-term (current) use of insulin",
      "Personal history of noncompliance with medical treatment, presenting hazards to health",
      "Asthma, unspecified type, unspecified",
      "Iron deficiency anemia, unspecified"
    ]
  }
}
